    <input id="f-title" name="title" required autocomplete="off" />
    <label for="f-author">Author</label>
    <input id="f-author" name="author" autocomplete="off" />
    <label for="f-notes">Notes</label>
    <textarea id="f-notes" name="notes"></textarea>
    <div class="actions">
      <button type="button" class="btn" id="cancel-add">Cancel</button>
      <button type="submit" class="btn primary">Add book</button>
    </div>
