  </form>
</div>

<script>
const app = document.getElementById('app');
const overlay = document.getElementById('overlay');
const addForm = document.getElementById('add-form');
const addError = document.getElementById('add-error');

function esc(s) {
  return String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

function fmtDate(ts) {
  if (!ts) return '';
  try { return new Date(ts).toLocaleDateString(); } catch { return ''; }
}

async function api(path, opts) {
  const res = await fetch(path, opts);
  if (!res.ok) {
    let msg = res.statusText || ('status ' + res.status);
    try { const j = await res.json(); if (j && j.error) msg = j.error; } catch {}
    throw new Error(msg);
  }
  if (res.status === 204) return null;
  return res.json();
}

function openAdd() { overlay.classList.add('show'); addError.textContent = ''; document.getElementById('f-title').focus(); }
function closeAdd() { overlay.classList.remove('show'); addForm.reset(); addError.textContent = ''; }

addForm.addEventListener('submit', async (e) => {
  e.preventDefault();
  addError.textContent = '';
  const fd = new FormData(addForm);
  try {
    await api('/api/books', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: fd.get('title').trim(),
        author: fd.get('author').trim(),
        notes: fd.get('notes').trim(),
      }),
    });
    closeAdd();
    render();
  } catch (err) {
    addError.textContent = 'Could not add book: ' + err.message;
  }
});
document.getElementById('cancel-add').addEventListener('click', closeAdd);
overlay.addEventListener('click', (e) => { if (e.target === overlay) closeAdd(); });

function cardHtml(b) {
  const finish = b.status === 'reading'
    ? `<button class="finish-btn" data-finish="${esc(b.id)}">Mark finished</button>`
    : `<span class="badge">finished</span>`;
  return `
    <div class="card">
      <a class="detail" href="/book/${esc(b.id)}">
        <div class="title">${esc(b.title)}</div>
        <div class="author">${esc(b.author || 'Unknown author')}</div>
        ${b.notes ? `<div class="notes">${esc(b.notes)}</div>` : ''}
      </a>
      ${finish}
    </div>`;
}

function listHtml(label, books) {
  if (!books.length) return `<section><h2>${label}</h2><div class="empty">Nothing here yet.</div></section>`;
  return `<section><h2>${label}</h2>${books.map(cardHtml).join('')}</section>`;
}

async function renderHome() {
  let books = [];
  try { books = await api('/api/books'); } catch (e) { app.innerHTML = `<div class="error">Could not load books: ${esc(e.message)}</div>`; return; }
  const reading = books.filter(b => b.status === 'reading');
  const finished = books.filter(b => b.status === 'finished')
    .sort((a, b) => (b.finishedAt || 0) - (a.finishedAt || 0));
  app.innerHTML = `
    <header>
      <h1><a href="/">Reading List</a></h1>
      <button class="add-btn" id="open-add">+ Add book</button>
    </header>
    ${listHtml('Currently reading', reading)}
    ${listHtml('Finished', finished)}`;
  document.getElementById('open-add').addEventListener('click', openAdd);
  app.querySelectorAll('[data-finish]').forEach(btn => {
    btn.addEventListener('click', async () => {
      btn.disabled = true;
      try { await api('/api/books/' + encodeURIComponent(btn.dataset.finish) + '/finish', { method: 'POST' }); render(); }
      catch (e) { alert('Could not mark finished: ' + e.message); btn.disabled = false; }
    });
  });
}

async function renderDetail(id) {
  let b;
  try { b = await api('/api/books/' + encodeURIComponent(id)); }
  catch (e) { app.innerHTML = `<div class="detail-head"><a class="back" href="/">← Back</a></div><div class="error">Book not found.</div>`; return; }

  app.innerHTML = `
    <div class="detail-head">
      <a class="back" href="/">← Back to list</a>
      <h1>${esc(b.title)}</h1>
      <div class="author">${esc(b.author || 'Unknown author')}</div>
      <div class="meta">${b.status === 'finished' ? 'Finished' : 'Currently reading'}${b.finishedAt ? ' · ' + fmtDate(b.finishedAt) : ''}${b.addedAt ? ' · added ' + fmtDate(b.addedAt) : ''}</div>
      <div class="share">
        <input id="share-url" readonly value="${esc(location.origin + '/book/' + b.id)}" />
        <button class="btn" id="copy-link">Copy link</button>
      </div>
    </div>
    <div class="detail-section">
      <h2>Notes</h2>
      <textarea class="edit-notes" id="notes-area">${esc(b.notes || '')}</textarea>
      <div class="actions" style="margin-top:12px">
        <button class="btn" id="toggle-status">${b.status === 'reading' ? 'Mark finished' : 'Mark as reading again'}</button>
        <button class="btn primary" id="save-notes">Save notes</button>
      </div>
      <div class="error" id="detail-error"></div>
    </div>`;

  const errEl = document.getElementById('detail-error');
  document.getElementById('copy-link').addEventListener('click', () => {
    const inp = document.getElementById('share-url');
    inp.select();
    navigator.clipboard.writeText(inp.value).then(() => {
      const btn = document.getElementById('copy-link');
      const old = btn.textContent; btn.textContent = 'Copied!';
      setTimeout(() => btn.textContent = old, 1500);
    }).catch(() => { document.execCommand('copy'); });
  });
  document.getElementById('save-notes').addEventListener('click', async () => {
    errEl.textContent = '';
    try {
      await api('/api/books/' + encodeURIComponent(id), {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ notes: document.getElementById('notes-area').value }),
      });
      const btn = document.getElementById('save-notes');
      btn.textContent = 'Saved';
      setTimeout(() => btn.textContent = 'Save notes', 1500);
    } catch (e) { errEl.textContent = 'Could not save: ' + e.message; }
  });
  document.getElementById('toggle-status').addEventListener('click', async () => {
    errEl.textContent = '';
    try {
      await api('/api/books/' + encodeURIComponent(id) + '/finish', { method: 'POST' });
      renderDetail(id);
    } catch (e) { errEl.textContent = 'Could not update: ' + e.message; }
  });
}

function route() {
  const m = location.pathname.match(/^\/book\/([^/]+)$/);
  if (m) renderDetail(decodeURIComponent(m[1]));
  else renderHome();
}

window.addEventListener('popstate', route);
route();
</script>
</body>
</html>
