{"content": "import { createServer } from 'node:http';
import { readFile, writeFile, access } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const DATA_FILE = process.env.BOOKS_FILE || join(__dirname, 'books.json');
const PORT = Number(process.env.PORT || 3000);

const HTML_FILE = join(__dirname, 'public', 'index.html');
let htmlCache = null;

async function readBooks() {
  try {
    await access(DATA_FILE);
    const raw = await readFile(DATA_FILE, 'utf8');
    const data = JSON.parse(raw);
    return Array.isArray(data) ? data : (Array.isArray(data.books) ? data.books : []);
  } catch (err) {
    if (err && err.code === 'ENOENT') return [];
    // Corrupt or unreadable file: start empty rather than crash.
    console.error('Warning: could not read books file, starting empty:', err.message);
    return [];
  }
}

async function writeBooks(books) {
  await writeFile(DATA_FILE, JSON.stringify({ books }, null, 2), 'utf8');
}

async function getHtml() {
  if (htmlCache) return htmlCache;
  htmlCache = await readFile(HTML_FILE, 'utf8');
  return htmlCache;
}

function send(res, status, body, headers = {}) {
  res.writeHead(status, headers);
  res.end(body);
}
function sendJson(res, status, obj) {
  send(res, status, JSON.stringify(obj), { 'Content-Type': 'application/json; charset=utf-8' });
}
function sendText(res, status, msg) {
  send(res, status, msg, { 'Content-Type': 'text/plain; charset=utf-8' });
}

async function readJsonBody(req) {
  const chunks = [];
  for await (const c of req) chunks.push(c);
  const raw = Buffer.concat(chunks).toString('utf8');
  if (!raw.trim()) return {};
  try { return JSON.parse(raw); } catch { throw new Error('Invalid JSON'); }
}

function cleanBook(input) {
  const title = String(input.title ?? '').trim();
  const author = String(input.author ?? '').trim();
  const notes = String(input.notes ?? '').trim();
  return { title, author, notes };
}

const router = [
  // Home + shareable book page both serve the same SPA.
  { method: 'GET', match: (u) => u === '/' || u === '/index.html', handler: async (_req, res) => {
    send(res, 200, await getHtml(), { 'Content-Type': 'text/html; charset=utf-8' });
  }},
  { method: 'GET', match: (u) => /^\/book\/[^/]+$/.test(u), handler: async (_req, res) => {
    send(res, 200, await getHtml(), { 'Content-Type': 'text/html; charset=utf-8' });
  }},

  // API: list
  { method: 'GET', match: (u) => u === '/api/books', handler: async (_req, res) => {
    sendJson(res, 200, await readBooks());
  }},

  // API: get one
  { method: 'GET', match: (u) => /^\/api\/books\/[^/]+$/.test(u), handler: async (req, res) => {
    const id = decodeURIComponent(req.url.split('/').pop());
    const book = (await readBooks()).find(b => b.id === id);
    if (!book) return sendJson(res, 404, { error: 'Book not found' });
    sendJson(res, 200, book);
  }},

  // API: add
  { method: 'POST', match: (u) => u === '/api/books', handler: async (req, res) => {
    let body;
    try { body = await readJsonBody(req); } catch { return sendJson(res, 400, { error: 'Invalid JSON' }); }
    const { title, author, notes } = cleanBook(body);
    if (!title) return sendJson(res, 400, { error: 'Title is required' });
    const books = await readBooks();
    const book = { id: randomUUID(), title, author, notes, status: 'reading', addedAt: Date.now(), finishedAt: null };
    books.push(book);
    await writeBooks(books);
    sendJson(res, 201, book);
  }},

  // API: toggle finish
  { method: 'POST', match: (u) => /^\/api\/books\/[^/]+\/finish$/.test(u), handler: async (req, res) => {
    const parts = req.url.split('/');
    const id = decodeURIComponent(parts[parts.length - 2]);
    const books = await readBooks();
    const book = books.find(b => b.id === id);
    if (!book) return sendJson(res, 404, { error: 'Book not found' });
    if (book.status === 'reading') { book.status = 'finished'; book.finishedAt = Date.now(); }
    else { book.status = 'reading'; book.finishedAt = null; }
    await writeBooks(books);
    sendJson(res, 200, book);
  }},

  // API: update notes
  { method: 'PATCH', match: (u) => /^\/api\/books\/[^/]+$/.test(u), handler: async (req, res) => {
    const id = decodeURIComponent(req.url.split('/').pop());
    let body;
    try { body = await readJsonBody(req); } catch { return sendJson(res, 400, { error: 'Invalid JSON' }); }
    const books = await readBooks();
    const book = books.find(b => b.id === id);
    if (!book) return sendJson(res, 404, { error: 'Book not found' });
    if (typeof body.notes === 'string') book.notes = body.notes.trim();
    if (typeof body.title === 'string' && body.title.trim()) book.title = body.title.trim();
    if (typeof body.author === 'string') book.author = body.author.trim();
    await writeBooks(books);
    sendJson(res, 200, book);
  }},
];

const server = createServer(async (req, res) => {
  const url = req.url.split('?')[0];
  try {
    for (const r of router) {
      if (r.method === req.method && r.match(url)) {
        return await r.handler(req, res);
      }
    }
    if (url === '/favicon.ico') return sendText(res, 204, '');
    sendText(res, 404, 'Not found');
  } catch (err) {
    console.error('Server error:', err);
    sendJson(res, 500, { error: 'Server error' });
  }
});

server.listen(PORT, () => {
  console.log(`Reading List running at http://localhost:${PORT}`);
});
", "path": "server.js"}

