{"content": "import { spawnSync } from 'node:child_process';
import { writeFileSync, readFileSync, unlinkSync, existsSync } from 'node:fs';
import { join } from 'node:path';

const ROOT = '/workspace';
const DATA = join(ROOT, 'books.json');
try { unlinkSync(DATA); } catch {}

function curl(args) {
  const r = spawnSync('curl', ['-s', ...args], { encoding: 'utf8' });
  return r.stdout.trim();
}

function runServer() {
  return spawnSync('node', ['server.js'], { cwd: ROOT, encoding: 'utf8' });
}

// start server in background via a detached-ish approach using & won't work with spawnSync;
// use a script that starts, waits, curls, then kills via pkill.
const start = spawnSync('bash', ['-c', `cd ${ROOT} && node server.js & echo $! > /tmp/srv.pid; sleep 1.2`], { encoding: 'utf8' });
console.log('server:', start.stdout, start.stderr);

let pass = 0, fail = 0;
function check(name, cond, extra = '') {
  if (cond) { pass++; console.log('  ok  -', name); }
  else { fail++; console.log('  FAIL-', name, extra); }
}

// add book 1
const b1 = JSON.parse(curl(['-X', 'POST', 'http://localhost:3000/api/books', '-H', 'Content-Type: application/json', '-d', JSON.stringify({ title: 'The Pragmatic Programmer', author: 'Hunt & Thomas', notes: 'reread chapter 1' })]));
check('add returns id', !!b1.id, JSON.stringify(b1));
check('add status reading', b1.status === 'reading');

// add book 2
const b2 = JSON.parse(curl(['-X', 'POST', 'http://localhost:3000/api/books', '-H', 'Content-Type: application/json', '-d', JSON.stringify({ title: 'Hyperion', author: 'Dan Simmons' })]));
check('add book2', !!b2.id);

// list
const list = JSON.parse(curl(['http://localhost:3000/api/books']));
check('list has 2', list.length === 2, JSON.stringify(list));

// finish book 1
const fin = JSON.parse(curl(['-X', 'POST', `http://localhost:3000/api/books/${b1.id}/finish`]));
check('finish status', fin.status === 'finished');
check('finish sets finishedAt', !!fin.finishedAt);

// get single
const one = JSON.parse(curl([`http://localhost:3000/api/books/${b1.id}`]));
check('get single title', one.title === 'The Pragmatic Programmer');

// patch notes
const patched = JSON.parse(curl(['-X', 'PATCH', `http://localhost:3000/api/books/${b1.id}`, '-H', 'Content-Type: application/json', '-d', JSON.stringify({ notes: 'updated notes here' })]));
check('patch notes', patched.notes === 'updated notes here');

// validation: empty title
const bad = JSON.parse(curl(['-X', 'POST', 'http://localhost:3000/api/books', '-H', 'Content-Type: application/json', '-d', JSON.stringify({ title: '   ' })]));
check('rejects empty title', bad.error && bad.error.includes('required'));

// not found
const nf = JSON.parse(curl(['http://localhost:3000/api/books/does-not-exist']));
check('404 not found', nf.error === 'Book not found');

// shareable page returns html
const page = curl(['-o', '/dev/null', '-w', '%{http_code}', `http://localhost:3000/book/${b1.id}`]);
check('shareable page 200', page === '200', page);

// file on disk
check('books.json exists', existsSync(DATA));
const onDisk = JSON.parse(readFileSync(DATA, 'utf8'));
check('disk has 2 books', onDisk.books.length === 2);

// restart persistence
spawnSync('bash', ['-c', 'pkill -f "node server.js"; sleep 0.5'], { encoding: 'utf8' });
spawnSync('bash', ['-c', `cd ${ROOT} && node server.js & sleep 1.2`], { encoding: 'utf8' });
const after = JSON.parse(curl(['http://localhost:3000/api/books']));
check('persisted across restart', after.length === 2, JSON.stringify(after));
check('finished status persisted', after.find(b => b.id === b1.id).status === 'finished');
check('notes persisted', after.find(b => b.id === b1.id).notes === 'updated notes here');

spawnSync('bash', ['-c', 'pkill -f "node server.js"'], { encoding: 'utf8' });
try { unlinkSync(DATA); } catch {}

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
